// Filter filters the input field.
func (m CookieFilter) Filter(in zapcore.Field) zapcore.Field {
	filterCookies := func(cookieHeader string) string {
		originRequest := http.Request{Header: http.Header{"Cookie": []string{cookieHeader}}}
		cookies := originRequest.Cookies()
		transformedRequest := http.Request{Header: make(http.Header)}

	OUTER:
		for _, c := range cookies {
			for _, a := range m.Actions {
				if c.Name != a.Name {
					continue
				}

				switch a.Type {
				case replaceAction:
					c.Value = a.Value
					transformedRequest.AddCookie(c)
					continue OUTER

				case hashAction:
					c.Value = hash(c.Value)
					transformedRequest.AddCookie(c)
					continue OUTER

				case deleteAction:
					continue OUTER
				}
			}

			transformedRequest.AddCookie(c)
		}

		return transformedRequest.Header.Get("Cookie")
	}

	// Cookie headers are usually encoded as an array of strings, but they can
	// also be passed as a plain string depending on the field being filtered.
	switch vals := in.Interface.(type) {
	case caddyhttp.LoggableStringArray:
		filtered := make(caddyhttp.LoggableStringArray, len(vals))
		for i, val := range vals {
			filtered[i] = filterCookies(val)
		}
		in.Interface = filtered

	case []string:
		filtered := make([]string, len(vals))
		for i, val := range vals {
			filtered[i] = filterCookies(val)
		}
		in.Interface = filtered

	default:
		in.String = filterCookies(in.String)
	}

	return in
}

